import { ButtonHTMLAttributes, ChangeEvent, ClipboardEvent, FormEvent, ReactNode, createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react'
import { Link, NavLink, Navigate, Route, Routes, useLocation, useNavigate, useSearchParams } from 'react-router-dom'
import { QRCodeSVG } from 'qrcode.react'
import {
  AtSign, BarChart3, Bell, CalendarDays, Check, ChevronDown, ChevronRight, CircleHelp, Clipboard, Copy, CreditCard,
  Eye, EyeOff, FileText, Globe2, Home, LayoutDashboard, Link2, Lock, LogOut, MapPin, Menu, MoreHorizontal, Pencil,
  Plus, Search, Settings, Share2, ShoppingCart, Sun, Trash2, Upload, UserRound, UtensilsCrossed, WalletCards, X, Zap,
} from 'lucide-react'
import { Order, Platform, Product, Profile, Sale, Status, asset, baseOrders, baseSales, initialProfile, menuProducts, planData, platformAssets, productBreakdown, saleCatalog } from './data'

const money = (value: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value)
const classNames = (...names: Array<string | false | undefined>) => names.filter(Boolean).join(' ')
const appKey = (suffix: string) => `bandeja.${suffix}`

function getStored<T>(key: string, fallback: T): T {
  try { const raw = localStorage.getItem(appKey(key)); return raw ? JSON.parse(raw) as T : fallback } catch { return fallback }
}
function useStored<T>(key: string, fallback: T) {
  const [value, setValue] = useState<T>(() => getStored(key, fallback))
  const save = useCallback((next: T | ((prev: T) => T)) => setValue(prev => {
    const resolved = typeof next === 'function' ? (next as (p: T) => T)(prev) : next
    localStorage.setItem(appKey(key), JSON.stringify(resolved)); return resolved
  }), [key])
  return [value, save] as const
}

type Busy = { message: string; result?: string; error?: boolean }
type Toast = { text: string; tone?: 'success' | 'error' } | null
type CartLine = { product: Product; quantity: number }
type AppContextValue = {
  mode: 'demo' | 'vazio'; profile: Profile; setProfile: (profile: Profile) => void
  products: Product[]; addProduct: (product: Product) => void; updateProduct: (product: Product) => void; removeProduct: (id: string) => void
  sales: Sale[]; orders: Order[]; addSaleAndOrder: (sale: Sale, order: Order) => void; updateOrder: (id: number, status: Status) => void
  connected: Platform[]; setConnected: (platform: Platform, active: boolean) => void
  cart: CartLine[]; addCart: (product: Product) => void; setCart: (cart: CartLine[]) => void
  sidebarCompact: boolean; setSidebarCompact: (value: boolean) => void
  connectClosed: boolean; setConnectClosed: (value: boolean) => void
  runBusy: (message: string, result: string, callback?: () => void, duration?: number, error?: boolean) => void
  toast: (text: string, tone?: 'success' | 'error') => void
}
const AppContext = createContext<AppContextValue | null>(null)
const useApp = () => { const value = useContext(AppContext); if (!value) throw new Error('Contexto Bandeja indisponível'); return value }

function isLoggedIn() { return localStorage.getItem(appKey('session')) === 'true' || sessionStorage.getItem(appKey('session')) === 'true' }
function setSession(remember: boolean) { (remember ? localStorage : sessionStorage).setItem(appKey('session'), 'true') }
function clearSession() { localStorage.removeItem(appKey('session')); sessionStorage.removeItem(appKey('session')) }

function BandejaProvider({ children }: { children: ReactNode }) {
  const location = useLocation()
  const [savedMode, setSavedMode] = useStored<'demo' | 'vazio'>('mode', 'demo')
  const [profile, setProfile] = useStored<Profile>('profile', initialProfile)
  const [extraProducts, setExtraProducts] = useStored<Product[]>('extra-products', [])
  const [productEdits, setProductEdits] = useStored<Record<string, Product>>('product-edits', {})
  const [removedProducts, setRemovedProducts] = useStored<string[]>('removed-products', [])
  const [extraSales, setExtraSales] = useStored<Sale[]>('extra-sales', [])
  const [extraOrders, setExtraOrders] = useStored<Order[]>('extra-orders', [])
  const [orderUpdates, setOrderUpdates] = useStored<Record<number, Status>>('order-updates', {})
  const [connected, setConnectedState] = useStored<Platform[]>('connected', [])
  const [cart, setCart] = useStored<CartLine[]>('cart', [])
  const [sidebarCompact, setSidebarCompact] = useStored('sidebar-compact', false)
  const [connectClosed, setConnectClosed] = useStored('connect-card-closed', false)
  const [busy, setBusy] = useState<Busy | null>(null)
  const [toastMessage, setToastMessage] = useState<Toast>(null)

  useEffect(() => {
    const requested = new URLSearchParams(location.search).get('dados')
    if (requested === 'demo' || requested === 'vazio') setSavedMode(requested)
  }, [location.search, setSavedMode])
  useEffect(() => {
    ;(window as Window & { __bandeja?: { reset: () => void } }).__bandeja = {
      reset: () => { Object.keys(localStorage).filter(key => key.startsWith('bandeja.')).forEach(key => localStorage.removeItem(key)); window.location.assign('/login') },
    }
  }, [])

  const products = useMemo(() => {
    const base = savedMode === 'demo' ? menuProducts : []
    return [...base, ...extraProducts].filter(product => !removedProducts.includes(product.id)).map(product => productEdits[product.id] ?? product)
  }, [extraProducts, productEdits, removedProducts, savedMode])
  const sales = useMemo(() => (savedMode === 'demo' ? [...extraSales, ...baseSales] : [...extraSales]), [extraSales, savedMode])
  const orders = useMemo(() => {
    const base = savedMode === 'demo' ? baseOrders : []
    return [...extraOrders, ...base].map(order => orderUpdates[order.id] ? { ...order, status: orderUpdates[order.id] } : order)
  }, [extraOrders, orderUpdates, savedMode])
  const toast = useCallback((text: string, tone: 'success' | 'error' = 'success') => { setToastMessage({ text, tone }); window.setTimeout(() => setToastMessage(null), 2800) }, [])
  const runBusy = useCallback((message: string, result: string, callback?: () => void, duration = 1000, error = false) => {
    setBusy({ message }); window.setTimeout(() => { setBusy({ message, result, error }); window.setTimeout(() => { setBusy(null); callback?.() }, error ? 1100 : 1300) }, duration)
  }, [])
  const value: AppContextValue = {
    mode: savedMode, profile, setProfile, products,
    addProduct: product => setExtraProducts(old => [product, ...old]),
    updateProduct: product => { if (extraProducts.some(item => item.id === product.id)) setExtraProducts(old => old.map(item => item.id === product.id ? product : item)); else setProductEdits(old => ({ ...old, [product.id]: product })) },
    removeProduct: id => { if (extraProducts.some(item => item.id === id)) setExtraProducts(old => old.filter(item => item.id !== id)); else setRemovedProducts(old => [...old, id]) },
    sales, orders, addSaleAndOrder: (sale, order) => { setExtraSales(old => [sale, ...old]); setExtraOrders(old => [order, ...old]) },
    updateOrder: (id, status) => setOrderUpdates(old => ({ ...old, [id]: status })),
    connected, setConnected: (platform, active) => setConnectedState(old => active ? [...new Set([...old, platform])] : old.filter(item => item !== platform)),
    cart, addCart: product => setCart(old => { const found = old.find(line => line.product.id === product.id); return found ? old.map(line => line.product.id === product.id ? { ...line, quantity: line.quantity + 1 } : line) : [...old, { product, quantity: 1 }] }), setCart,
    sidebarCompact, setSidebarCompact, connectClosed, setConnectClosed, runBusy, toast,
  }
  return <AppContext.Provider value={value}>{children}<Feedback busy={busy} toast={toastMessage} /></AppContext.Provider>
}

function Feedback({ busy, toast }: { busy: Busy | null; toast: Toast }) {
  return <>{busy && <div className="feedback-layer" role="status" aria-live="assertive"><div className="feedback-card">{busy.result ? <div className={classNames('success-mark', busy.error && 'is-error')}>{busy.error ? <X /> : <Check />}</div> : <div className="conic-spinner" />}<strong>{busy.result ?? busy.message}</strong>{busy.result && !busy.error && <span className="confetti">✦ ✧ ✦</span>}</div></div>}{toast && <div className={classNames('toast', toast.tone === 'error' && 'error')} role="status">{toast.tone === 'error' ? <CircleHelp /> : <Check />}{toast.text}</div>}</>
}

function Modal({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  useEffect(() => { const handler = (event: KeyboardEvent) => event.key === 'Escape' && onClose(); window.addEventListener('keydown', handler); return () => window.removeEventListener('keydown', handler) }, [onClose])
  return <div className="modal-backdrop" onMouseDown={onClose} role="presentation"><section className={classNames('modal', wide && 'wide')} onMouseDown={event => event.stopPropagation()} role="dialog" aria-modal="true" aria-label={title}><header><h2>{title}</h2><button className="icon-button" aria-label="Fechar" onClick={onClose}><X /></button></header>{children}</section></div>
}

function Button({ children, className, ...props }: ButtonHTMLAttributes<HTMLButtonElement>) { return <button className={classNames('button', className)} {...props}>{children}</button> }
function PlatformMark({ platform, small = false }: { platform: Platform; small?: boolean }) { return <span className={classNames('platform-mark', small && 'small')}><img src={platformAssets[platform]} alt="" />{!small && <span>{platform}</span>}</span> }
function StatusBadge({ status }: { status: Status }) { return <span className={classNames('status', status === 'Concluído' && 'done', status === 'Cancelado' && 'cancel')}>{status}</span> }
function ProductPlaceholder({ product, className = '' }: { product: Product; className?: string }) { return product.image ? <img className={classNames('product-image', className)} src={product.image} alt={product.name} /> : <div className={classNames('product-image placeholder', className)}><UtensilsCrossed /><span>{product.name.split(' ').at(-1)}</span></div> }

function RequireAuth({ children }: { children: ReactNode }) { return isLoggedIn() ? <>{children}</> : <Navigate to="/login" replace /> }

export default function App() { return <BandejaProvider><Routes><Route path="/" element={<Landing />} /><Route path="/blog" element={<Blog />} /><Route path="/login" element={<Login />} /><Route path="/cadastro" element={<Signup />} /><Route path="/recuperar-senha" element={<PasswordRecovery />} /><Route path="/assinaturas" element={<Plans />} /><Route path="/app/*" element={<RequireAuth><AppLayout /></RequireAuth>} /><Route path="/:username" element={<PublicMenu />} /><Route path="*" element={<NotFound />} /></Routes></BandejaProvider> }

function Landing() {
  const [compact, setCompact] = useState(false); const [menu, setMenu] = useState<'product' | 'features' | null>(null)
  useEffect(() => { const onScroll = () => setCompact(window.scrollY > 42); window.addEventListener('scroll', onScroll); return () => window.removeEventListener('scroll', onScroll) }, [])
  const scrollTo = (id: string) => { document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' }); setMenu(null) }
  return <main className="landing"><header className={classNames('landing-nav', compact && 'compact')}><Link to="/" aria-label="Bandeja"><img src={asset('logo-escura.png')} alt="Bandeja" /></Link><nav><div className="nav-dropdown"><button onClick={() => setMenu(menu === 'product' ? null : 'product')}>Produto <ChevronDown /></button>{menu === 'product' && <div className="landing-popover"><button onClick={() => scrollTo('como-funciona')}>Como funciona</button><button onClick={() => scrollTo('cardapio')}>Cardápio digital</button><button onClick={() => scrollTo('analises')}>Análises</button></div>}</div><div className="nav-dropdown"><button onClick={() => setMenu(menu === 'features' ? null : 'features')}>Funcionalidades <ChevronDown /></button>{menu === 'features' && <div className="landing-popover"><button onClick={() => scrollTo('funcionalidades')}>Central de pedidos</button><button onClick={() => scrollTo('recursos')}>Recursos</button></div>}</div><button onClick={() => scrollTo('planos')}>Planos</button><button onClick={() => scrollTo('recursos')}>Recursos</button><Link to="/blog">Blog</Link></nav><Link className="button dark nav-cta" to="/cadastro">Criar conta</Link></header>
    <section className="hero"><div className="hero-copy"><h1>Sua administração<br />food em um só lugar.</h1><p>Conecte suas plataformas e tenha<br />uma melhor experiência.</p><div className="hero-actions"><Link className="button lime" to="/login">Entrar</Link><Link className="button soft" to="/cadastro">Criar conta</Link></div></div><div className="hero-lime"><div className="lime-orb" /><img src={asset('foto-pessoa.png')} alt="Empreendedora de food service" /></div></section>
    <section id="como-funciona" className="landing-section steps"><span className="eyebrow">SIMPLIFIQUE O DIA A DIA</span><h2>Uma bandeja para todos os seus pedidos.</h2><div className="step-grid"><article><b>01</b><h3>Crie sua conta</h3><p>Organize sua operação em poucos minutos, sem burocracia.</p></article><article><b>02</b><h3>Conecte seus canais</h3><p>Centralize delivery, pagamentos e pedidos em uma mesma visão.</p></article><article><b>03</b><h3>Compartilhe e venda</h3><p>Seu cardápio digital fica pronto para circular por link e QR code.</p></article></div></section>
    <section id="funcionalidades" className="landing-section feature-split"><div><span className="eyebrow">VISÃO COMPLETA</span><h2>Menos abas. Mais tempo para cuidar do sabor.</h2><p>Acompanhe faturamento, pedidos e os produtos que mais encantam seus clientes sem alternar entre aplicativos.</p><Link className="text-link" to="/cadastro">Conhecer a Bandeja <ChevronRight /></Link></div><div className="dashboard-shot"><img src={asset('mockup-dashboard.png')} alt="Painel Bandeja" /></div></section>
    <section id="analises" className="landing-section signal"><div className="signal-card"><BarChart3 /><h3>Decisões que cabem na palma da mão.</h3><p>Entenda onde estão suas vendas e descubra o que faz seus clientes voltarem.</p></div><div className="signal-stat"><strong>+12,5%</strong><span>variação em vendas</span></div><div className="signal-stat"><strong>1 link</strong><span>para começar a vender</span></div></section>
    <section id="cardapio" className="landing-section cardapio-promo"><div className="qr-deco"><QRCodeSVG value="https://bandeja.com/usuario01" size={148} /></div><div><span className="eyebrow">SEU ESPAÇO DIGITAL</span><h2>Seu cardápio, do seu jeito.</h2><p>Crie uma vitrine bonita, compartilhe com clientes e receba pedidos diretamente pelo link.</p><Link className="button dark" to="/cadastro">Criar meu cardápio</Link></div></section>
    <section id="planos" className="landing-section"><div className="section-heading"><span className="eyebrow">PLANOS</span><h2>Comece hoje. Cresça no seu ritmo.</h2></div><PricingCards /></section>
    <section id="recursos" className="landing-section faq"><span className="eyebrow">RECURSOS</span><h2>Perguntas frequentes</h2><details open><summary>Preciso integrar algum aplicativo para usar?</summary><p>Não. Você pode começar com o cardápio digital e ligar seus canais quando quiser.</p></details><details><summary>O link do cardápio é compartilhável?</summary><p>Sim. Ele funciona pelo navegador e também pode ser aberto pelo QR code.</p></details><details><summary>Há cobrança para começar?</summary><p>O plano Essencial é gratuito para você experimentar a operação.</p></details></section>
    <section className="landing-final"><h2>Coloque sua operação na Bandeja.</h2><Link className="button dark" to="/cadastro">Criar conta grátis</Link></section><footer><img src={asset('logo-clara.png')} alt="Bandeja" /><span>© 2026 Bandeja. Feito para quem alimenta a cidade.</span></footer>
  </main>
}

function Blog() { return <main className="blog-page"><Link className="blog-brand" to="/"><img src={asset('logo-escura.png')} alt="Bandeja" /></Link><h1>Ideias que deixam sua operação mais leve.</h1><div className="post-grid">{['Como organizar pedidos de vários canais', 'Seu cardápio online pode vender mais', 'Cinco números que todo restaurante deve acompanhar'].map((title, i) => <article key={title}><span>0{i + 1} · Gestão food</span><h2>{title}</h2><p>Uma leitura rápida para deixar sua rotina mais simples e previsível.</p><a href="#post">Ler artigo <ChevronRight /></a></article>)}</div></main> }

function AuthShell({ children, heading = 'Compartilhe um link e comece a vender hoje.' }: { children: ReactNode; heading?: string }) { return <main className="auth-page"><section className="auth-form"><Link to="/"><img src={asset('logo-escura.png')} alt="Bandeja" /></Link><div className="auth-inner">{children}</div></section><aside className="auth-showcase"><h1>{heading}</h1><img src={asset('mockup-dashboard.png')} alt="Painel Bandeja" /></aside></main> }

function Login() {
  const navigate = useNavigate(); const { runBusy } = useApp(); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [remember, setRemember] = useState(true); const [show, setShow] = useState(false); const [errors, setErrors] = useState<Record<string, string>>({})
  if (isLoggedIn()) return <Navigate to="/app" replace />
  const submit = (event: FormEvent) => { event.preventDefault(); const next: Record<string, string> = {}; if (!/^\S+@\S+\.\S+$/.test(email)) next.email = 'Digite um e-mail válido.'; if (password.length < 6) next.password = 'A senha deve ter pelo menos 6 caracteres.'; setErrors(next); if (Object.keys(next).length) return; setSession(remember); runBusy('Organizando sua conta...', 'Tudo pronto!', () => navigate('/app'), 3000) }
  const google = () => { setSession(true); runBusy('Organizando sua conta...', 'Tudo pronto!', () => navigate('/app'), 1200) }
  return <AuthShell><h2>Entrar</h2><p>Entre com seus dados para acessar sua conta.</p><form onSubmit={submit}><label>E-mail<input value={email} placeholder="seuemail@exemplo.com" onChange={event => setEmail(event.target.value)} autoComplete="email" />{errors.email && <small className="field-error">{errors.email}</small>}</label><label>Senha<div className="input-icon"><input value={password} type={show ? 'text' : 'password'} placeholder="Digite sua senha" onChange={event => setPassword(event.target.value)} autoComplete="current-password" /><button type="button" onClick={() => setShow(!show)} aria-label="Mostrar senha">{show ? <EyeOff /> : <Eye />}</button></div>{errors.password && <small className="field-error">{errors.password}</small>}</label><div className="auth-options"><label className="checkbox"><input type="checkbox" checked={remember} onChange={event => setRemember(event.target.checked)} /> Lembrar de mim</label><Link to="/recuperar-senha">Esqueci a senha</Link></div><Button className="dark full" type="submit">Entrar</Button></form><div className="divider"><span />ou continue com<span /></div><Button className="google full" type="button" onClick={google}><b className="google-g">G</b> Entrar com Google</Button><p className="auth-foot">Novo por aqui? <Link to="/cadastro">Criar conta</Link></p></AuthShell>
}

function Signup() {
  const navigate = useNavigate(); const [form, setForm] = useState({ name: '', email: '', password: '', confirm: '', terms: false }); const [error, setError] = useState('')
  const submit = (event: FormEvent) => { event.preventDefault(); if (!form.name || !/^\S+@\S+\.\S+$/.test(form.email) || form.password.length < 6 || form.password !== form.confirm || !form.terms) { setError('Revise os dados e aceite os termos para continuar.'); return } localStorage.setItem(appKey('pending-profile'), JSON.stringify({ ...initialProfile, name: form.name, email: form.email, username: form.name.toLowerCase().replace(/\s+/g, '').slice(0, 18) })); navigate('/assinaturas') }
  return <AuthShell heading="Seu negócio pronto para vender em qualquer lugar."><h2>Criar conta</h2><p>Comece a organizar sua operação hoje.</p><form onSubmit={submit}><label>Nome<input placeholder="Como podemos te chamar?" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></label><label>E-mail<input placeholder="seuemail@exemplo.com" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} /></label><label>Senha<input type="password" placeholder="Mínimo de 6 caracteres" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} /></label><label>Confirmar senha<input type="password" placeholder="Repita a senha" value={form.confirm} onChange={e => setForm({ ...form, confirm: e.target.value })} /></label><label className="checkbox"><input type="checkbox" checked={form.terms} onChange={e => setForm({ ...form, terms: e.target.checked })} /> Aceito os termos de uso e a política de privacidade.</label>{error && <small className="field-error">{error}</small>}<Button className="dark full" type="submit">Continuar</Button></form><p className="auth-foot">Já tem uma conta? <Link to="/login">Entrar</Link></p></AuthShell>
}

function PasswordRecovery() {
  const navigate = useNavigate(); const { toast } = useApp(); const [step, setStep] = useState<'email' | 'otp' | 'password'>('email'); const [email, setEmail] = useState(''); const [digits, setDigits] = useState(['', '', '', '', '', '']); const [password, setPassword] = useState(''); const refs = useRef<Array<HTMLInputElement | null>>([]); const [seconds, setSeconds] = useState(30)
  useEffect(() => { if (step !== 'otp' || seconds <= 0) return; const timer = window.setTimeout(() => setSeconds(value => value - 1), 1000); return () => clearTimeout(timer) }, [seconds, step])
  const onOtp = (index: number, value: string) => { const digit = value.replace(/\D/g, '').slice(-1); const next = [...digits]; next[index] = digit; setDigits(next); if (digit && index < 5) refs.current[index + 1]?.focus(); if (next.every(Boolean)) toast('Código verificado') }
  const paste = (event: ClipboardEvent<HTMLInputElement>) => { const incoming = event.clipboardData.getData('text').replace(/\D/g, '').slice(0, 6); if (incoming.length === 6) { event.preventDefault(); setDigits(incoming.split('')); refs.current[5]?.focus() } }
  return <AuthShell heading="Recupere o acesso e volte a vender."><div className="recovery">{step === 'email' && <><h2>Recuperar senha</h2><p>Informe seu e-mail para receber um código de verificação.</p><form onSubmit={event => { event.preventDefault(); if (/^\S+@\S+\.\S+$/.test(email)) setStep('otp'); else toast('Digite um e-mail válido', 'error') }}><label>E-mail<input autoFocus placeholder="seuemail@exemplo.com" value={email} onChange={e => setEmail(e.target.value)} /></label><Button className="dark full">Enviar código</Button></form></>}{step === 'otp' && <><h2>Verifique seu e-mail</h2><p>Enviamos um código de 6 dígitos para <strong>{email}</strong>.</p><div className="otp-row">{digits.map((digit, index) => <input key={index} ref={element => { refs.current[index] = element }} value={digit} maxLength={1} inputMode="numeric" onPaste={paste} onChange={e => onOtp(index, e.target.value)} onKeyDown={e => { if (e.key === 'Backspace' && !digits[index] && index) refs.current[index - 1]?.focus() }} />)}</div><Button className="dark full" disabled={!digits.every(Boolean)} onClick={() => setStep('password')}>Continuar</Button><button className="plain-link" disabled={seconds > 0} onClick={() => { setSeconds(30); toast('Um novo código foi enviado') }}>{seconds ? `Reenviar código em ${seconds}s` : 'Reenviar código'}</button></>}{step === 'password' && <><h2>Nova senha</h2><p>Escolha uma senha segura para sua conta.</p><form onSubmit={e => { e.preventDefault(); if (password.length < 6) return toast('A senha deve ter pelo menos 6 caracteres', 'error'); toast('Senha redefinida com sucesso'); window.setTimeout(() => navigate('/login'), 850) }}><label>Nova senha<input autoFocus type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="Mínimo de 6 caracteres" /></label><Button className="dark full">Salvar nova senha</Button></form></>}</div></AuthShell>
}

function PricingCards({ onSelect }: { onSelect?: (plan: string) => void }) { return <div className="pricing-grid">{planData.map(plan => <article className={classNames('plan-card', plan.dark && 'plus')} key={plan.name}>{plan.popular && <span className="popular">Mais usado</span>}<h3>{plan.name}</h3><p>{plan.description}</p><hr /><div className="price"><strong>{plan.price}</strong><span>/mês</span></div><ul>{plan.benefits.map(benefit => <li key={benefit}><Check />{benefit}</li>)}</ul><Button className={classNames('full', plan.name === 'Avançado' && 'lime', plan.name !== 'Avançado' && (plan.dark ? 'white' : 'dark'))} onClick={() => onSelect?.(plan.name)}>{plan.cta}</Button></article>)}</div> }

function Plans() {
  const navigate = useNavigate(); const { runBusy, setProfile, toast } = useApp(); const [coupon, setCoupon] = useState(''); const [couponMessage, setCouponMessage] = useState('')
  const choose = (plan: string) => { localStorage.setItem(appKey('plan'), plan); const pending = localStorage.getItem(appKey('pending-profile')); if (pending) { setProfile(JSON.parse(pending) as Profile); localStorage.removeItem(appKey('pending-profile')) } setSession(true); runBusy('Organizando sua conta...', `Plano ${plan} ativado`, () => navigate('/app'), 3000) }
  const applyCoupon = () => { if (!coupon.trim()) return setCouponMessage('Digite um cupom para aplicar.'); if (coupon.trim().toUpperCase() === 'BANDEJA10') { localStorage.setItem(appKey('coupon'), 'BANDEJA10'); setCouponMessage('Cupom aplicado: 10% de desconto visual.'); toast('Cupom aplicado') } else setCouponMessage('Este cupom não é válido.') }
  return <main className="plans-page"><Link className="plans-logo" to="/"><img src={asset('logo-escura.png')} alt="Bandeja" /></Link><div className="plans-inner"><PricingCards onSelect={choose} /><section className="coupon"><span className="coupon-icon">⌁</span><div><h3>Adicionar cupom</h3><p>Tem um cupom de desconto? Digite abaixo para aplicar.</p></div><div className="coupon-input"><input value={coupon} placeholder="Digite o código do cupom" onChange={e => { setCoupon(e.target.value); setCouponMessage('') }} /><Button className="dark" onClick={applyCoupon}>Aplicar</Button></div>{couponMessage && <small className={classNames('coupon-message', couponMessage.startsWith('Cupom') && 'ok')}>{couponMessage}</small>}</section></div></main>
}

const appNav = [
  { to: '/app', label: 'Início', icon: Home, end: true }, { to: '/app/historico', label: 'Histórico de vendas', icon: WalletCards },
  { to: '/app/cardapio', label: 'Meu cardápio', icon: UtensilsCrossed }, { to: '/app/pedidos', label: 'Pedidos', icon: FileText },
  { to: '/app/analise', label: 'Análise', icon: BarChart3 }, { to: '/app/plugins', label: 'Plugins', icon: Zap },
]
const appFooterNav = [{ to: '/app/perfil', label: 'Perfil', icon: UserRound }, { to: '/app/configuracoes', label: 'Configurações', icon: Settings }]
const crumbLabels: Record<string, string> = { '/app': 'Dashboard', '/app/historico': 'Histórico de vendas', '/app/cardapio': 'Meu cardápio', '/app/pedidos': 'Pedidos', '/app/analise': 'Análise', '/app/plugins': 'Plugins', '/app/perfil': 'Perfil', '/app/configuracoes': 'Configurações' }

function AppLayout() {
  const { profile, sidebarCompact, setSidebarCompact } = useApp(); const location = useLocation(); const navigate = useNavigate(); const [open, setOpen] = useState(false); const label = crumbLabels[location.pathname] ?? 'Dashboard'
  const leave = () => { clearSession(); navigate('/login') }
  const side = <aside className={classNames('sidebar', sidebarCompact && 'compact', open && 'open')}><Link className="side-logo" to="/app"><img src={asset('logo-escura.png')} alt="Bandeja" /></Link><div className="side-user"><img src={profile.avatar || asset('avatar-padrao.jpg')} alt="" /><div><strong>{profile.name}</strong><span>@{profile.username}</span></div><button title="Recolher menu" onClick={() => setSidebarCompact(!sidebarCompact)}>{sidebarCompact ? <ChevronRight /> : <LayoutDashboard />}</button></div><nav className="side-nav">{appNav.map(({ to, label: navLabel, icon: Icon, end }) => <NavLink key={to} to={to} end={end} onClick={() => setOpen(false)}><Icon /><span>{navLabel}</span></NavLink>)}</nav><nav className="side-footer">{appFooterNav.map(({ to, label: navLabel, icon: Icon }) => <NavLink key={to} to={to} onClick={() => setOpen(false)}><Icon /><span>{navLabel}</span></NavLink>)}<button onClick={leave}><LogOut /><span>Sair</span></button></nav></aside>
  return <div className="app-shell">{side}<main className="app-main"><header className="topbar"><button className="mobile-menu" onClick={() => setOpen(!open)}><Menu /></button><span>Início</span><b>/</b><strong>{label}</strong></header><div className="app-content"><Routes><Route index element={<Dashboard />} /><Route path="historico" element={<SalesHistory />} /><Route path="cardapio" element={<MenuPage />} /><Route path="pedidos" element={<OrdersPage />} /><Route path="analise" element={<Analytics />} /><Route path="plugins" element={<Plugins />} /><Route path="perfil" element={<ProfilePage />} /><Route path="configuracoes" element={<SettingsPage />} /><Route path="*" element={<NotFound />} /></Routes></div></main>{open && <button className="drawer-backdrop" aria-label="Fechar menu" onClick={() => setOpen(false)} />}</div>
}

function Donut({ platform = false, total = 'R$ 12.450,32' }: { platform?: boolean; total?: string }) { return <div className={classNames('donut', platform && 'platform')} title="Passe o mouse para explorar os dados"><div><strong>{total}</strong><span>Total</span></div></div> }
function EmptyState({ type = 'vendas', action, small = false }: { type?: 'vendas' | 'produtos' | 'pedidos'; action?: () => void; small?: boolean }) { const details = type === 'produtos' ? { title: 'Nenhum produto encontrado.', text: 'Adicione um novo produto para começar a montar seu cardápio.', action: 'Adicionar um novo produto', Icon: UtensilsCrossed } : type === 'pedidos' ? { title: 'Nenhum pedido encontrado.', text: 'Compartilhe seu cardápio para começar a receber pedidos.', action: 'Compartilhar cardápio', Icon: FileText } : { title: 'Nenhuma venda encontrada.', text: 'Compartilhe seu cardápio para começar a receber pedidos.', action: 'Compartilhar cardápio', Icon: CreditCard }; const Icon = details.Icon; return <div className={classNames('empty-state', small && 'small')}><div className="empty-icon"><Icon /></div><h3>{details.title}</h3><p>{details.text}</p>{action && <Button className="lime" onClick={action}>{type === 'produtos' ? <Plus /> : <Share2 />}{details.action}</Button>}</div> }

function ShareMenu({ onClose }: { onClose: () => void }) { const { profile, toast } = useApp(); const link = `bandeja.com/${profile.username}`; const copy = async () => { try { await navigator.clipboard.writeText(link); toast('Link copiado') } catch { toast('Não foi possível copiar', 'error') } }; const download = () => { const svg = document.getElementById('share-qr')?.outerHTML; if (!svg) return; const image = new Image(); image.onload = () => { const canvas = document.createElement('canvas'); canvas.width = 600; canvas.height = 600; const ctx = canvas.getContext('2d'); ctx?.drawImage(image, 0, 0); const anchor = document.createElement('a'); anchor.download = 'qr-code-bandeja.png'; anchor.href = canvas.toDataURL('image/png'); anchor.click() }; image.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}` }; return <Modal title="Compartilhe seu cardápio" onClose={onClose}><div className="share-modal"><QRCodeSVG id="share-qr" value={`https://${link}`} size={192} /><p>Envie este link para seus clientes começarem a pedir.</p><div className="share-link"><span>{link}</span><button onClick={copy} aria-label="Copiar link"><Copy /></button></div><Button className="dark full" onClick={download}><Upload />Baixar QR code</Button></div></Modal> }

function Dashboard() {
  const { profile, mode, sales, orders, connected, connectClosed, setConnectClosed, addSaleAndOrder, runBusy, toast } = useApp(); const [saleOpen, setSaleOpen] = useState(false); const [shareOpen, setShareOpen] = useState(false); const [moreOpen, setMoreOpen] = useState(false); const hasData = sales.length > 0; const total = mode === 'demo' ? 'R$ 12.450,32' : 'R$ 0,00'; const count = mode === 'demo' ? 368 + Math.max(0, orders.length - 9) : orders.length
  const copy = async () => { try { await navigator.clipboard.writeText(`bandeja.com/${profile.username}`); toast('Link copiado') } catch { setShareOpen(true) } }
  return <><div className="dashboard-title"><div><h1>Olá, {profile.name}.</h1><p>Acompanhe suas vendas em um só lugar.</p></div><Button className="dark" onClick={() => setSaleOpen(true)}><Plus />Nova venda</Button></div><section className="kpis"><div><span>Faturamento total</span><b>{total}</b></div><div><span>Pedidos</span><b>{count}</b></div><div><span>Ticket médio</span><b>{mode === 'demo' ? 'R$ 33,84' : 'R$ 0,00'}</b></div><div><span>Variação (30 dias)</span><b className="positive">{mode === 'demo' ? '+12,5%' : '—'}</b></div></section><section className="dashboard-grid"><article className="surface recent-card">{!connectClosed && connected.length === 0 ? <ConnectPlatforms onDismiss={() => setConnectClosed(true)} /> : hasData ? <RecentSales sales={sales.slice(0, 11)} /> : <EmptyState small action={() => setShareOpen(true)} />}</article><article className="surface sales-donut"><h2>Vendas este mês</h2><div className="donut-layout"><Donut total={total} /><div className="legend">{productBreakdown.map((item, index) => <div key={item.name}><i style={{ backgroundColor: item.color }} /><p><strong>{item.name}</strong><span>{item.amount}</span></p><b>{item.pct}</b>{index === 3 && <button className="text-link inline" onClick={() => setMoreOpen(true)}>( Ver mais )</button>}</div>)}</div></div></article><article className="surface share-card"><h2>Compartilhe seu link de pedidos</h2><div><QRCodeSVG value={`https://bandeja.com/${profile.username}`} size={124} /><section><label>Link do seu cardápio</label><button className="dashboard-link" onClick={copy}>bandeja.com/{profile.username}<Copy /></button><p>Compartilhe esse link com seus clientes para receber pedidos.</p></section></div></article><article className="surface last-orders"><div className="card-heading"><h2>Últimos pedidos</h2><Link to="/app/pedidos">Ver todos</Link></div>{orders.slice(0, 5).map(order => <div className="last-order" key={order.id}><span>#{order.id}</span><span>{order.items[0].replace(/^\d+×\s*/, '')}</span><time>{order.time}</time><StatusBadge status={order.status} /></div>)}</article></section>{saleOpen && <NewSaleModal onClose={() => setSaleOpen(false)} onSave={(sale, order) => runBusy('Salvando...', 'Venda adicionada', () => { addSaleAndOrder(sale, order); setSaleOpen(false) })} />}{shareOpen && <ShareMenu onClose={() => setShareOpen(false)} />}{moreOpen && <Modal title="Produtos menos vendidos" onClose={() => setMoreOpen(false)}><p className="muted">Veja os produtos com menor participação nas vendas deste mês.</p><ul className="simple-list"><li>Refrigerante <b>31 vendas</b></li><li>Suco natural <b>26 vendas</b></li><li>Coxinha <b>21 vendas</b></li></ul></Modal>}</>
}

function ConnectPlatforms({ onDismiss }: { onDismiss: () => void }) { const navigate = useNavigate(); return <div className="connect-card"><button className="icon-button close" onClick={onDismiss} aria-label="Fechar"><X /></button><h2>Conecte suas plataformas</h2><p>Traga extratos de forma automática de outros apps de vendas para que você tenha um controle maior.</p><img src={asset('logos-plataformas.png')} alt="iFood, 99Food, Rappi e Asaas" /><Button className="lime" onClick={() => navigate('/app/plugins')}><Link2 />Conectar plataformas</Button></div> }
function RecentSales({ sales }: { sales: Sale[] }) { return <div className="recent-list">{sales.map(sale => <div key={sale.id}><span>{sale.product}</span><PlatformMark platform={sale.platform} small /><span>{sale.customer}</span><b>{money(sale.value)}</b><time>{sale.date} {sale.time}</time></div>)}</div> }
function NewSaleModal({ onClose, onSave }: { onClose: () => void; onSave: (sale: Sale, order: Order) => void }) { const { orders } = useApp(); const [form, setForm] = useState({ product: saleCatalog[0].name, quantity: 1, customer: '', platform: 'Bandeja' as Platform, status: 'Concluído' as Status }); const catalogItem = saleCatalog.find(item => item.name === form.product) ?? saleCatalog[0]; const submit = (event: FormEvent) => { event.preventDefault(); if (!form.customer.trim()) return; const time = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }); const id = Math.max(...orders.map(order => order.id), 1024) + 1; const value = catalogItem.price * Number(form.quantity); onSave({ id: `V-${id}`, product: form.product, platform: form.platform, customer: form.customer, value, date: '18/10/2026', time, status: form.status }, { id, platform: form.platform, status: form.status === 'Cancelado' ? 'Cancelado' : 'Em andamento', time, customer: form.customer, phone: '—', items: [`${form.quantity}× ${form.product}`], total: value }) }; return <Modal title="Nova venda" onClose={onClose}><form className="modal-form" onSubmit={submit}><label>Produto<select value={form.product} onChange={e => setForm({ ...form, product: e.target.value })}>{saleCatalog.map(item => <option key={item.name}>{item.name}</option>)}</select></label><label>Quantidade<input type="number" min="1" value={form.quantity} onChange={e => setForm({ ...form, quantity: Number(e.target.value) })} /></label><label>Cliente<input autoFocus required placeholder="Nome do cliente" value={form.customer} onChange={e => setForm({ ...form, customer: e.target.value })} /></label><label>Plataforma<select value={form.platform} onChange={e => setForm({ ...form, platform: e.target.value as Platform })}>{(['Bandeja', 'iFood', '99Food', 'Rappi'] as Platform[]).map(platform => <option key={platform}>{platform}</option>)}</select></label><label>Status<select value={form.status} onChange={e => setForm({ ...form, status: e.target.value as Status })}>{(['Concluído', 'Em andamento', 'Cancelado'] as Status[]).map(status => <option key={status}>{status}</option>)}</select></label><div className="modal-total">Total <b>{money(catalogItem.price * form.quantity)}</b></div><Button className="dark full">Salvar venda</Button></form></Modal> }

function SalesHistory() {
  const { sales } = useApp(); const [query, setQuery] = useState(''); const [platform, setPlatform] = useState(''); const [product, setProduct] = useState(''); const [status, setStatus] = useState(''); const [detail, setDetail] = useState<Sale | null>(null); const [shareOpen, setShareOpen] = useState(false)
  const filtered = sales.filter(sale => `${sale.product} ${sale.platform} ${sale.customer}`.toLowerCase().includes(query.toLowerCase()) && (!platform || sale.platform === platform) && (!product || sale.product === product) && (!status || sale.status === status))
  return <><section className="page-heading"><h1>Histórico de vendas</h1></section><div className="filter-row"><label className="search-input"><Search /><input placeholder="Buscar por produto, plataforma ou cliente..." value={query} onChange={e => setQuery(e.target.value)} /></label><select value={platform} onChange={e => setPlatform(e.target.value)}><option value="">Todas as plataformas</option>{(['Bandeja', 'iFood', '99Food', 'Rappi'] as Platform[]).map(item => <option key={item}>{item}</option>)}</select><select value={product} onChange={e => setProduct(e.target.value)}><option value="">Todos os produtos</option>{Array.from(new Set(sales.map(item => item.product))).map(item => <option key={item}>{item}</option>)}</select><select value={status} onChange={e => setStatus(e.target.value)}><option value="">Todos os status</option>{(['Concluído', 'Em andamento', 'Cancelado'] as Status[]).map(item => <option key={item}>{item}</option>)}</select></div>{filtered.length ? <div className="table-wrap surface"><table className="sales-table"><thead><tr><th>Produto</th><th>Plataforma</th><th>Cliente</th><th>Valor</th><th>Data e horário</th><th>Status</th><th /></tr></thead><tbody>{filtered.map(sale => <tr key={sale.id}><td>{sale.product}</td><td><PlatformMark platform={sale.platform} /></td><td>{sale.customer}</td><td><b>{money(sale.value)}</b></td><td>{sale.date} &nbsp; {sale.time}</td><td><StatusBadge status={sale.status} /></td><td><button className="more" onClick={() => setDetail(sale)}><MoreHorizontal /></button></td></tr>)}</tbody></table></div> : <EmptyState action={() => setShareOpen(true)} />}{detail && <SaleDetail sale={detail} onClose={() => setDetail(null)} />}{shareOpen && <ShareMenu onClose={() => setShareOpen(false)} />}</>
}

function SaleDetail({ sale, onClose }: { sale: Sale; onClose: () => void }) { const { toast } = useApp(); return <Modal title="Detalhes da venda" onClose={onClose}><dl className="detail-list"><div><dt>Produto</dt><dd>{sale.product}</dd></div><div><dt>Cliente</dt><dd>{sale.customer}</dd></div><div><dt>Plataforma</dt><dd><PlatformMark platform={sale.platform} /></dd></div><div><dt>Data</dt><dd>{sale.date} às {sale.time}</dd></div><div><dt>Total</dt><dd>{money(sale.value)}</dd></div></dl><Button className="soft full" onClick={() => { navigator.clipboard.writeText(sale.id); toast('ID da venda copiado') }}><Clipboard />Copiar ID</Button></Modal> }

function OrdersPage() {
  const { orders, updateOrder } = useApp(); const [query, setQuery] = useState(''); const [status, setStatus] = useState(''); const [platform, setPlatform] = useState(''); const [period, setPeriod] = useState('Hoje'); const [detail, setDetail] = useState<Order | null>(null); const [shareOpen, setShareOpen] = useState(false); const [cancel, setCancel] = useState<Order | null>(null)
  const visible = orders.filter(order => `${order.id} ${order.customer} ${order.platform} ${order.items.join(' ')}`.toLowerCase().includes(query.toLowerCase()) && (!status || order.status === status) && (!platform || order.platform === platform))
  return <><div className="order-filters"><label className="search-input"><Search /><input placeholder="Buscar pedidos..." value={query} onChange={e => setQuery(e.target.value)} /></label><select value={status} onChange={e => setStatus(e.target.value)}><option value="">Todos os status</option>{(['Em andamento', 'Concluído', 'Cancelado'] as Status[]).map(item => <option key={item}>{item}</option>)}</select><select value={platform} onChange={e => setPlatform(e.target.value)}><option value="">Todas as plataformas</option>{(['Bandeja', 'iFood', '99Food', 'Rappi'] as Platform[]).map(item => <option key={item}>{item}</option>)}</select><select value={period} onChange={e => setPeriod(e.target.value)}><option>Hoje</option><option>Ontem</option><option>Últimos 7 dias</option><option>Últimos 30 dias</option><option>Todos</option></select></div>{visible.length ? <div className="order-grid">{visible.map(order => <OrderCard key={order.id} order={order} onDetail={() => setDetail(order)} onReady={() => updateOrder(order.id, 'Concluído')} onCancel={() => setCancel(order)} />)}</div> : <EmptyState type="pedidos" action={() => setShareOpen(true)} />}{detail && <OrderDetail order={detail} onClose={() => setDetail(null)} />}{cancel && <Modal title="Cancelar pedido?" onClose={() => setCancel(null)}><p className="muted">Esta ação altera o status do pedido #{cancel.id} para cancelado.</p><div className="modal-actions"><Button className="soft" onClick={() => setCancel(null)}>Voltar</Button><Button className="dark" onClick={() => { updateOrder(cancel.id, 'Cancelado'); setCancel(null) }}>Cancelar pedido</Button></div></Modal>}{shareOpen && <ShareMenu onClose={() => setShareOpen(false)} />}</>
}

function OrderCard({ order, onDetail, onReady, onCancel }: { order: Order; onDetail: () => void; onReady: () => void; onCancel: () => void }) { const [menu, setMenu] = useState(false); return <article className="order-card surface"><header><strong>#{order.id}</strong><PlatformMark platform={order.platform} small /><StatusBadge status={order.status} /><time>{order.time}</time><button className="more" onClick={() => setMenu(!menu)}><MoreHorizontal /></button>{menu && <div className="context-menu"><button onClick={onDetail}>Ver detalhes</button>{order.status === 'Em andamento' && <button onClick={() => { setMenu(false); onReady() }}>Marcar como pronto</button>}{order.status !== 'Cancelado' && <button className="danger-text" onClick={() => { setMenu(false); onCancel() }}>Cancelar pedido</button>}</div>}</header><h3>{order.customer}</h3><p>{order.phone}</p><ul>{order.items.map(item => <li key={item}>{item}</li>)}</ul><div className="order-total"><span>Total</span><b>{money(order.total)}</b></div>{order.status === 'Em andamento' ? <Button className="dark full" onClick={onReady}>Marcar como pronto</Button> : <div className={classNames('order-finish', order.status === 'Cancelado' && 'cancel')} >{order.status === 'Cancelado' ? <X /> : <Check />}{order.status === 'Cancelado' ? 'Pedido cancelado' : 'Pedido concluído'}</div>}</article> }
function OrderDetail({ order, onClose }: { order: Order; onClose: () => void }) { return <Modal title={`Pedido #${order.id}`} onClose={onClose}><dl className="detail-list"><div><dt>Cliente</dt><dd>{order.customer}</dd></div><div><dt>Telefone</dt><dd>{order.phone}</dd></div><div><dt>Plataforma</dt><dd><PlatformMark platform={order.platform} /></dd></div><div><dt>Status</dt><dd><StatusBadge status={order.status} /></dd></div><div><dt>Itens</dt><dd>{order.items.join(', ')}</dd></div><div><dt>Total</dt><dd>{money(order.total)}</dd></div></dl></Modal> }

function MenuPage() {
  const { profile, setProfile, products, addProduct, updateProduct, removeProduct, addCart, cart, setCart, orders, addSaleAndOrder, runBusy, toast } = useApp(); const [query, setQuery] = useState(''); const [productModal, setProductModal] = useState<Product | 'new' | null>(null); const [detail, setDetail] = useState<Product | null>(null); const [cartOpen, setCartOpen] = useState(false); const [shareOpen, setShareOpen] = useState(false); const coverRef = useRef<HTMLInputElement>(null); const avatarRef = useRef<HTMLInputElement>(null)
  const changeImage = (event: ChangeEvent<HTMLInputElement>, field: 'avatar' | 'cover') => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => runBusy('Salvando...', field === 'avatar' ? 'Foto de perfil salva' : 'Capa salva', () => setProfile({ ...profile, [field]: reader.result as string })); reader.readAsDataURL(file) }
  const checkout = (customer: string, phone: string) => { const total = cart.reduce((sum, line) => sum + line.product.price * line.quantity, 0); const id = Math.max(...orders.map(order => order.id), 1024) + 1; const time = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }); const first = cart[0]; runBusy('Salvando...', 'Pedido finalizado!', () => { addSaleAndOrder({ id: `V-${id}`, product: first.product.name, platform: 'Bandeja', customer, value: total, date: '18/10/2026', time, status: 'Em andamento' }, { id, platform: 'Bandeja', status: 'Em andamento', time, customer, phone, items: cart.map(line => `${line.quantity}× ${line.product.name}`), total }); setCart([]); setCartOpen(false); toast('Seu pedido foi enviado para a Bandeja') }) }
  const visible = products.filter(product => `${product.name} ${product.description}`.toLowerCase().includes(query.toLowerCase()))
  return <><section className="menu-page"><div className="menu-cover" style={profile.cover ? { backgroundImage: `url(${profile.cover})` } : undefined}><button className="cover-edit" onClick={() => coverRef.current?.click()} aria-label="Editar capa"><Pencil /></button><input ref={coverRef} type="file" accept="image/*" hidden onChange={event => changeImage(event, 'cover')} /></div><div className="menu-profile"><div className="menu-avatar"><img src={profile.avatar || asset('avatar-padrao.jpg')} alt="" /><button onClick={() => avatarRef.current?.click()} aria-label="Editar foto"><Pencil /></button><input ref={avatarRef} type="file" accept="image/*" hidden onChange={event => changeImage(event, 'avatar')} /></div><div className="business-info"><InlineEdit value={profile.business} className="business-name" onSave={business => setProfile({ ...profile, business })} /><div><span><UtensilsCrossed /> <InlineEdit value={profile.category} onSave={category => setProfile({ ...profile, category })} /></span><i /> <span><MapPin /> <InlineEdit value={profile.location || 'Adicione uma localização'} onSave={location => setProfile({ ...profile, location })} /></span></div><InlineEdit value={profile.bio || 'Escreva aqui sua biografia.'} className="business-bio" onSave={bio => setProfile({ ...profile, bio })} /></div><div className="menu-actions"><button className="whatsapp" onClick={() => { if (profile.phone) window.open(`https://wa.me/${profile.phone.replace(/\D/g, '')}`, '_blank', 'noopener'); else toast('Cadastre seu WhatsApp no Perfil', 'error') }}><img src={asset('icone-whatsapp.jpg')} alt="WhatsApp" /></button><button onClick={() => setCartOpen(true)}><ShoppingCart /><em>{cart.length || ''}</em></button><button onClick={() => setShareOpen(true)}><Share2 /></button></div></div><label className="menu-search"><Search /><input placeholder="Buscar produtos..." value={query} onChange={e => setQuery(e.target.value)} /></label>{visible.length ? <div className="menu-product-grid">{visible.map(product => <ProductCard key={product.id} product={product} onView={() => setDetail(product)} onBuy={() => { addCart(product); toast(`${product.name} adicionado ao carrinho`) }} />)}<button className="add-product-card" onClick={() => setProductModal('new')}><Plus /><span>Adicionar produto</span></button></div> : <EmptyState type="produtos" action={() => setProductModal('new')} />}</section>{productModal && <ProductModal product={productModal === 'new' ? undefined : productModal} onClose={() => setProductModal(null)} onSave={product => { if (productModal === 'new') addProduct(product); else updateProduct(product); setProductModal(null); toast('Produto salvo') }} />}{detail && <ProductDetail product={detail} onClose={() => setDetail(null)} onEdit={() => { setProductModal(detail); setDetail(null) }} onDelete={() => { removeProduct(detail.id); setDetail(null); toast('Produto excluído') }} />}{cartOpen && <CartDrawer onClose={() => setCartOpen(false)} onCheckout={checkout} />}{shareOpen && <ShareMenu onClose={() => setShareOpen(false)} />}</>
}

function InlineEdit({ value, onSave, className = '' }: { value: string; onSave: (value: string) => void; className?: string }) { const [editing, setEditing] = useState(false); const [draft, setDraft] = useState(value); useEffect(() => setDraft(value), [value]); if (editing) return <input className={classNames('inline-edit-input', className)} autoFocus value={draft} onChange={e => setDraft(e.target.value)} onBlur={() => { setEditing(false); if (draft.trim()) onSave(draft.trim()) }} onKeyDown={e => { if (e.key === 'Enter') (e.currentTarget as HTMLInputElement).blur(); if (e.key === 'Escape') { setDraft(value); setEditing(false) } }} />; return <button className={classNames('inline-edit', className)} onClick={() => setEditing(true)}>{value}</button> }
function ProductCard({ product, onView, onBuy }: { product: Product; onView: () => void; onBuy: () => void }) { return <article className="menu-product surface"><ProductPlaceholder product={product} /><div><h3>{product.name}</h3><p>{product.description}</p><b>{money(product.price)}</b><div><Button className="outline" onClick={onView}>Ver</Button><Button className="dark" onClick={onBuy}>Comprar</Button></div></div></article> }
function ProductModal({ product, onClose, onSave }: { product?: Product; onClose: () => void; onSave: (product: Product) => void }) { const [form, setForm] = useState<Product>(product ?? { id: `P-${Date.now()}`, name: '', description: '', price: 0 }); const [error, setError] = useState(''); const picture = useRef<HTMLInputElement>(null); const onImage = (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => setForm({ ...form, image: reader.result as string }); reader.readAsDataURL(file) }; return <Modal title={product ? 'Editar produto' : 'Adicionar produto'} onClose={onClose}><form className="modal-form" onSubmit={e => { e.preventDefault(); if (!form.name || !form.description || form.price <= 0) return setError('Preencha nome, descrição e um preço válido.'); onSave(form) }}><label>Nome do produto<input autoFocus value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></label><label>Descrição<textarea value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} /></label><label>Preço<input type="number" step="0.01" min="0" value={form.price || ''} onChange={e => setForm({ ...form, price: Number(e.target.value) })} /></label><input ref={picture} type="file" accept="image/*" hidden onChange={onImage} /><Button type="button" className="soft full" onClick={() => picture.current?.click()}><Upload />{form.image ? 'Trocar imagem' : 'Adicionar imagem'}</Button>{error && <small className="field-error">{error}</small>}<Button className="dark full">Salvar produto</Button></form></Modal> }
function ProductDetail({ product, onClose, onEdit, onDelete }: { product: Product; onClose: () => void; onEdit: () => void; onDelete: () => void }) { return <Modal title={product.name} onClose={onClose}><ProductPlaceholder product={product} className="detail-product-image" /><p>{product.description}</p><h3>{money(product.price)}</h3><div className="modal-actions"><Button className="soft" onClick={onEdit}><Pencil />Editar</Button><Button className="danger" onClick={onDelete}><Trash2 />Excluir</Button></div></Modal> }
function CartDrawer({ onClose, onCheckout }: { onClose: () => void; onCheckout: (customer: string, phone: string) => void }) { const { cart, setCart } = useApp(); const [customer, setCustomer] = useState(''); const [phone, setPhone] = useState(''); const total = cart.reduce((sum, line) => sum + line.product.price * line.quantity, 0); const change = (id: string, offset: number) => setCart(cart.flatMap(line => line.product.id !== id ? [line] : line.quantity + offset < 1 ? [] : [{ ...line, quantity: line.quantity + offset }])); return <div className="cart-overlay" onMouseDown={onClose}><aside className="cart-drawer" onMouseDown={e => e.stopPropagation()}><header><h2>Seu carrinho</h2><button className="icon-button" onClick={onClose}><X /></button></header>{cart.length ? <><div className="cart-items">{cart.map(line => <article key={line.product.id}><ProductPlaceholder product={line.product} /><div><strong>{line.product.name}</strong><span>{money(line.product.price * line.quantity)}</span><div className="quantity"><button onClick={() => change(line.product.id, -1)}>−</button><b>{line.quantity}</b><button onClick={() => change(line.product.id, 1)}>+</button></div></div><button className="remove-cart" onClick={() => setCart(cart.filter(item => item.product.id !== line.product.id))}><Trash2 /></button></article>)}</div><div className="cart-total"><span>Total</span><b>{money(total)}</b></div><label>Seu nome<input value={customer} onChange={e => setCustomer(e.target.value)} placeholder="Como quer ser chamado?" /></label><label>Telefone<input value={phone} onChange={e => setPhone(e.target.value)} placeholder="(00) 00000-0000" /></label><Button className="dark full" disabled={!customer || !phone} onClick={() => onCheckout(customer, phone)}>Finalizar pedido</Button></> : <EmptyState type="produtos" small />}</aside></div> }

function Analytics() {
  const [params, setParams] = useSearchParams(); const tab = params.get('aba') === 'cardapio' ? 'cardapio' : 'vendas'; const [period, setPeriod] = useState(tab === 'cardapio' ? 'Últimos 30 dias' : 'Este mês'); const [more, setMore] = useState(false); const values = [65, 120, 195, 140, 280, 98, 152, 203, 155, 235, 288]; const labels = ['01', '04', '07', '10', '13', '16', '19', '22', '25', '28', '30']
  return <><div className="analysis-toolbar"><div className="analysis-tabs"><button className={tab === 'vendas' ? 'active' : ''} onClick={() => { setParams({}); setPeriod('Este mês') }}><BarChart3 />Vendas</button><button className={tab === 'cardapio' ? 'active' : ''} onClick={() => { setParams({ aba: 'cardapio' }); setPeriod('Últimos 30 dias') }}><UtensilsCrossed />Cardápio</button></div><label className="period-select"><CalendarDays /><select value={period} onChange={e => setPeriod(e.target.value)}><option>Hoje</option><option>Últimos 7 dias</option><option>Últimos 30 dias</option><option>Este mês</option></select></label></div>{tab === 'vendas' ? <div className="analysis-grid"><article className="surface analysis-card"><h1>Vendas este mês</h1><p>Produtos mais vendidos do seu cardápio</p><div className="analysis-donut"><Donut /> <Legend onMore={() => setMore(true)} /></div></article><article className="surface analysis-card"><h1>Vendas por plataforma</h1><p>Total de vendas em cada aplicativo</p><div className="analysis-donut"><Donut platform /><div className="platform-legend"><div><PlatformMark platform="Bandeja" /><p>320 vendas</p><b>72,7%</b></div><div><PlatformMark platform="iFood" /><p>105 vendas</p><b>23,9%</b></div><div><PlatformMark platform="99Food" /><p>15 vendas</p><b>3,4%</b></div></div></div></article></div> : <article className="surface chart-card"><h1>Visualizações do cardápio</h1><p>Veja quantas vezes seu cardápio foi visualizado nos últimos 30 dias</p><span className="chart-period"><CalendarDays />{period}</span><strong className="view-count">{period === 'Últimos 30 dias' ? '1.450' : '247'}</strong><span className="view-label">visualizações</span><div className="bars" role="img" aria-label="Gráfico de barras de visualizações nos últimos trinta dias">{values.map((value, i) => <div className="bar-column" key={labels[i]} title={`${labels[i]}/10 — ${value} visualizações`}><i style={{ height: `${value / 3}%` }} /><span>{labels[i]}</span></div>)}</div></article>}{more && <Modal title="Produtos menos vendidos" onClose={() => setMore(false)}><p className="muted">Refrigerante, suco natural e coxinha somam 78 vendas no período.</p></Modal>}</>
}
function Legend({ onMore }: { onMore: () => void }) { return <div className="legend">{productBreakdown.map((item, index) => <div key={item.name}><i style={{ backgroundColor: item.color }} /><p><strong>{item.name}</strong><span>{item.amount}</span></p><b>{item.pct}</b>{index === 3 && <button className="text-link inline" onClick={onMore}>( Ver mais )</button>}</div>)}</div> }

function Plugins() {
  const { connected, setConnected, runBusy, toast } = useApp(); const [params] = useSearchParams(); const failure = params.get('falhar')?.toLowerCase(); const plugins: Array<{ name: Platform; description: string }> = [{ name: 'iFood', description: 'Conecte sua conta do iFood e receba seus pedidos.' }, { name: '99Food', description: 'Conecte sua conta da 99Food e centralize seus pedidos em um só lugar.' }, { name: 'Rappi', description: 'Conecte sua conta da Rappi e gerencie seus pedidos de forma simples e organizada.' }, { name: 'ASaaS', description: 'Conecte sua conta do ASaaS e receba os pagamentos dos seus pedidos de forma segura e automática.' }]
  const connect = (platform: Platform) => { const failed = failure === platform.toLowerCase().replace('99food', '99food'); runBusy(`Conectando ${platform}...`, failed ? 'Não foi possível conectar' : `${platform} conectado`, () => { if (!failed) { setConnected(platform, true); toast(`${platform} conectado`) } }, 4000, failed) }
  return <section className="plugins-page"><div className="page-heading"><h1>Plugins</h1><p>Conecte suas plataformas de delivery e recebimentos para automatizar seus pedidos e pagamentos.</p></div><div className="plugin-list">{plugins.map(plugin => <article className="surface plugin-row" key={plugin.name}><img src={platformAssets[plugin.name]} alt="" /><div><h2>{plugin.name}</h2><p>{plugin.description}</p></div>{connected.includes(plugin.name) ? <div className="plugin-connected"><span><Check />Conectado</span><Button className="outline" onClick={() => setConnected(plugin.name, false)}>Desconectar</Button></div> : <Button className="dark" onClick={() => connect(plugin.name)}>Conectar</Button>}</article>)}</div></section>
}

function ProfilePage() {
  const { profile, setProfile, runBusy, toast } = useApp(); const [draft, setDraft] = useState(profile); const [error, setError] = useState(''); const avatarRef = useRef<HTMLInputElement>(null); const coverRef = useRef<HTMLInputElement>(null); useEffect(() => setDraft(profile), [profile]); const upload = (event: ChangeEvent<HTMLInputElement>, key: 'avatar' | 'cover') => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { const next = { ...draft, [key]: reader.result as string }; setDraft(next); runBusy('Salvando...', key === 'avatar' ? 'Foto de perfil salva' : 'Capa salva', () => setProfile(next)) }; reader.readAsDataURL(file) }; const save = () => { if (!/^\S+@\S+\.\S+$/.test(draft.email) || !/^[a-z0-9]+$/.test(draft.username)) return setError('Use um e-mail válido e um usuário minúsculo, sem espaços.'); runBusy('Salvando...', 'Alterações salvas', () => { setProfile(draft); toast('Perfil atualizado') }) }
  const fields: Array<[keyof Profile, string, typeof UserRound]> = [['name', 'Nome', UserRound], ['username', 'Nome de usuário', AtSign], ['email', 'E-mail', FileText], ['phone', 'WhatsApp', Bell]]
  return <section className="profile-page"><div className="page-heading"><h1>Perfil</h1><p>Gerencie suas informações pessoais.</p></div><article className="profile-hero surface"><div className="profile-cover" style={draft.cover ? { backgroundImage: `url(${draft.cover})` } : undefined}><button onClick={() => coverRef.current?.click()}><Pencil /></button><input ref={coverRef} type="file" hidden accept="image/*" onChange={e => upload(e, 'cover')} /></div><div className="profile-avatar"><img src={draft.avatar || asset('avatar-padrao.jpg')} alt="" /><button onClick={() => avatarRef.current?.click()}><Pencil /></button><input ref={avatarRef} type="file" hidden accept="image/*" onChange={e => upload(e, 'avatar')} /></div><h2>{draft.name}</h2><span>@{draft.username}</span></article><div className="profile-fields">{fields.map(([key, label, Icon]) => <label className="surface" key={key}><Icon /><strong>{label}</strong><input value={draft[key] as string} onChange={e => setDraft({ ...draft, [key]: e.target.value })} /></label>)}</div>{error && <p className="field-error">{error}</p>}<Button className="dark save-profile" onClick={save}>Salvar alterações</Button></section>
}

function Toggle({ value, onChange, label }: { value: boolean; onChange: (value: boolean) => void; label: string }) { return <button aria-label={label} role="switch" aria-checked={value} className={classNames('toggle', value && 'on')} onClick={() => onChange(!value)}><span /></button> }
function SettingsPage() { const navigate = useNavigate(); const { runBusy, toast } = useApp(); const [dark, setDark] = useStored('dark-toggle', false); const [notifications, setNotifications] = useStored('notifications', true); const [passwordOpen, setPasswordOpen] = useState(false); return <section className="settings-page"><div className="page-heading"><h1>Configurações</h1><p>Gerencie as preferências da sua conta.</p></div><div className="settings-list"><article className="surface"><Sun /><div><h2>Modo escuro</h2><p>Altere entre o modo claro e escuro da plataforma.</p></div><Toggle value={dark} onChange={setDark} label="Modo escuro" /></article><article className="surface"><Bell /><div><h2>Notificações</h2><p>Receba avisos sobre novos pedidos e atualizações.</p></div><Toggle value={notifications} onChange={setNotifications} label="Notificações" /></article><article className="surface"><Globe2 /><div><h2>Idioma</h2><p>Escolha o idioma da plataforma.</p></div><select><option>Português (Brasil)</option><option disabled>English — Em breve</option><option disabled>Español — Em breve</option></select></article><article className="surface"><UserRound /><div><h2>Dados da conta</h2><p>Edite suas informações pessoais.</p></div><Button className="dark" onClick={() => navigate('/app/perfil')}>Editar</Button></article><article className="surface"><Lock /><div><h2>Segurança</h2><p>Altere sua senha de acesso.</p></div><Button className="dark" onClick={() => setPasswordOpen(true)}>Alterar senha</Button></article></div>{passwordOpen && <PasswordModal onClose={() => setPasswordOpen(false)} onSave={() => runBusy('Salvando...', 'Senha alterada', () => { setPasswordOpen(false); toast('Senha alterada com sucesso') })} />}</section> }
function PasswordModal({ onClose, onSave }: { onClose: () => void; onSave: () => void }) { const [passwords, setPasswords] = useState({ old: '', next: '', confirm: '' }); const [error, setError] = useState(''); return <Modal title="Alterar senha" onClose={onClose}><form className="modal-form" onSubmit={e => { e.preventDefault(); if (passwords.next.length < 6 || passwords.next !== passwords.confirm) return setError('A nova senha deve ter 6 caracteres e as confirmações devem ser iguais.'); onSave() }}><label>Senha atual<input type="password" value={passwords.old} onChange={e => setPasswords({ ...passwords, old: e.target.value })} /></label><label>Nova senha<input type="password" value={passwords.next} onChange={e => setPasswords({ ...passwords, next: e.target.value })} /></label><label>Confirmar nova senha<input type="password" value={passwords.confirm} onChange={e => setPasswords({ ...passwords, confirm: e.target.value })} /></label>{error && <small className="field-error">{error}</small>}<Button className="dark full">Salvar senha</Button></form></Modal> }

function PublicMenu() {
  const location = useLocation(); const { profile, products, addCart, cart, orders, addSaleAndOrder, setCart, runBusy, toast } = useApp(); const [query, setQuery] = useState(''); const [cartOpen, setCartOpen] = useState(false); const candidate = location.pathname.slice(1).toLowerCase(); if (candidate !== profile.username.toLowerCase()) return <NotFound />; const visible = products.filter(product => `${product.name} ${product.description}`.toLowerCase().includes(query.toLowerCase())); const checkout = (customer: string, phone: string) => { const total = cart.reduce((sum, line) => sum + line.product.price * line.quantity, 0); const id = Math.max(...orders.map(order => order.id), 1024) + 1; const time = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }); const first = cart[0]; runBusy('Salvando...', 'Pedido finalizado!', () => { addSaleAndOrder({ id: `V-${id}`, product: first.product.name, platform: 'Bandeja', customer, value: total, date: '18/10/2026', time, status: 'Em andamento' }, { id, platform: 'Bandeja', status: 'Em andamento', time, customer, phone, items: cart.map(line => `${line.quantity}× ${line.product.name}`), total }); setCart([]); setCartOpen(false); toast('Pedido recebido com sucesso') }) }
  return <main className="public-menu"><header><Link to="/"><img src={asset('logo-escura.png')} alt="Bandeja" /></Link><button onClick={() => setCartOpen(true)}><ShoppingCart />{cart.length ? <b>{cart.length}</b> : null}</button></header><section className="public-cover" style={profile.cover ? { backgroundImage: `url(${profile.cover})` } : undefined} /><section className="public-info"><img src={profile.avatar || asset('avatar-padrao.jpg')} alt="" /><div><h1>{profile.business}</h1><p><UtensilsCrossed /> {profile.category} <i /> <MapPin /> {profile.location}</p><span>{profile.bio}</span></div></section><label className="menu-search"><Search /><input placeholder="Buscar produtos..." value={query} onChange={e => setQuery(e.target.value)} /></label><section className="public-products">{visible.map(product => <article className="public-product surface" key={product.id}><ProductPlaceholder product={product} /><div><h2>{product.name}</h2><p>{product.description}</p><b>{money(product.price)}</b></div><Button className="dark" onClick={() => { addCart(product); toast(`${product.name} adicionado ao carrinho`) }}>Adicionar</Button></article>)}</section>{cartOpen && <CartDrawer onClose={() => setCartOpen(false)} onCheckout={checkout} />}</main>
}

function NotFound() { const home = isLoggedIn() ? '/app' : '/'; return <main className="not-found"><div className="sad-face">︵<span>?</span><span>?</span></div><h1>Página não encontrada.</h1><p>A página que você está procurando<br />não existe ou foi removida.</p><Link className="button lime" to={home}><Home />Voltar para início</Link></main> }
